import { T } from '../src/localize.ts';
import type { Activity, Drill, DrillItem, Localized } from '../src/types.ts';

// Quick drills: one per recurring error. Each item is a moment from a real talk and
// three ways to handle it; the explanation says why the best one works. Two minutes,
// in the learner's own language. Fresh, checked items are made when these run out.

type Tri = [en: string, uz: string, ru: string];
const L = ([en, uz, ru]: Tri): Localized => ({ en, uz, ru });
const P = ([en, uz, ru]: Tri) => T({ en, uz, ru });
const item = (id: string, prompt: Tri, options: Tri[], answer: number, explanation: Tri): DrillItem => ({ id, prompt: P(prompt), options: options.map(P), answer, explanation: L(explanation) });
const drill = (id: string, errorTag: string, node: string, title: Tri, explain: Tri, items: DrillItem[]): Drill => ({ id, kind: 'drill', errorTag, node, levels: [1, 5], minutes: 4, aiVariants: true, title: L(title), explain: L(explain), items });

export const drills: Activity[] = [
  drill('drill.fillers', 'filler_heavy', 'delivery.fillers', ['Swap fillers for pauses', 'To‘ldiruvchi so‘zlar o‘rniga pauza', 'Пауза вместо слов-паразитов'], ['A filler is a sound or word that fills the time while your brain looks for what to say next. A silent pause does the same job and sounds confident. Close your mouth at the end of a phrase, breathe, then go on.', 'To‘ldiruvchi so‘z — miyangiz keyin nima deyishni qidirayotganda vaqtni to‘ldiradigan tovush yoki so‘z. Jim pauza ham xuddi shu vazifani bajaradi va ishonchli eshitiladi. Ibora oxirida og‘zingizni yuming, nafas oling, keyin davom eting.', 'Слово-паразит — это звук или словечко, которым вы заполняете время, пока мозг ищет, что сказать дальше. Пауза в тишине делает то же самое, но звучит уверенно. В конце фразы закройте рот, вдохните и продолжайте.'], [
    item('f1', ['You lost your next word in the middle of a sentence. What is best?', 'Gap o‘rtasida keyingi so‘zni unutdingiz. Eng yaxshisi nima?', 'Вы потеряли следующее слово посреди фразы. Что лучше?'], [['Say "ee… um…" until it comes back.', '«Ee… aa…» deb, eslaguningizcha davom eting.', 'Говорить «эээ… ну…», пока не вспомните.'], ['Stop, breathe for a second in silence, then continue.', 'To‘xtang, bir soniya jim nafas oling, keyin davom eting.', 'Остановиться, секунду молча вдохнуть и продолжить.'], ['Apologise and start the sentence again.', 'Uzr so‘rang va gapni qaytadan boshlang.', 'Извиниться и начать фразу заново.']], 1, ['An audience hardly notices a one-second silence, but it does notice fillers and apologies.', 'Bir soniyalik jimlikni tinglovchilar deyarli sezmaydi, to‘ldiruvchi so‘z va uzrni esa sezadi.', 'Секундную паузу зал почти не замечает, а слова-паразиты и извинения — замечает.']),
    item('f2', ['Which line sounds most confident?', 'Qaysi gap eng ishonchli eshitiladi?', 'Какая фраза звучит увереннее всего?'], [['So, ee, basically, our idea is, like, an app.', 'Xullas, ee, qisqasi, g‘oyamiz, haligi, ilova.', 'Ну, короче, типа, наша идея — это, как бы, приложение.'], ['Our idea is an app. [pause] It saves farmers time.', 'G‘oyamiz — ilova. [pauza] U fermerlarning vaqtini tejaydi.', 'Наша идея — приложение. [пауза] Оно экономит фермерам время.'], ['Our idea is, um, maybe an app, I think.', 'G‘oyamiz, ee, ilova bo‘lsa kerak, menimcha.', 'Наша идея, эээ, наверное, приложение, мне кажется.']], 1, ['Short sentence, a pause, then the benefit: no fillers and no hedging.', 'Qisqa gap, pauza, keyin foyda: to‘ldiruvchi so‘zlarsiz va ikkilanishsiz.', 'Короткая фраза, пауза, затем польза: без слов-паразитов и оговорок.']),
    item('f3', ['Your report says 14 fillers per 100 words. What is the best first step?', 'Hisobotda 100 so‘zga 14 ta to‘ldiruvchi so‘z deyilgan. Eng yaxshi birinchi qadam qaysi?', 'В отчёте — 14 слов-паразитов на 100 слов. С чего лучше всего начать?'], [['Speak faster so there is no time for fillers.', 'To‘ldiruvchi so‘zlarga vaqt qolmasligi uchun tezroq gapiring.', 'Говорить быстрее, чтобы не оставалось времени на слова-паразиты.'], ['Find your one favourite filler and practise pausing where it usually comes.', 'Eng ko‘p ishlatadigan to‘ldiruvchi so‘zingizni toping va u odatda chiqadigan joyda pauza qilishni mashq qiling.', 'Найти своё самое частое слово-паразит и тренировать паузу там, где оно обычно появляется.'], ['Write the whole talk and read it out.', 'Butun nutqni yozib, o‘qib bering.', 'Написать всю речь и зачитать её.']], 1, ['Many speakers lean on one or two habit fillers; fixing those cuts the count fast.', 'Ko‘p odamlarda bir-ikkita odatiy to‘ldiruvchi so‘z bo‘ladi; ularni tuzatsangiz, son tez kamayadi.', 'У многих есть одно-два привычных слова-паразита; убрав их, вы быстро снизите счёт.']),
    item('f4', ['Where do fillers most often appear?', 'To‘ldiruvchi so‘zlar ko‘pincha qayerda paydo bo‘ladi?', 'Где чаще всего появляются слова-паразиты?'], [['At the start of a sentence and between ideas.', 'Gap boshida va fikrlar orasida.', 'В начале фразы и между мыслями.'], ['Only at the end of the talk.', 'Faqat nutq oxirida.', 'Только в конце выступления.'], ['Only in the middle of long words.', 'Faqat uzun so‘zlar o‘rtasida.', 'Только в середине длинных слов.']], 0, ['That is where the brain plans the next idea, so that is where to place a pause.', 'Aynan shu yerda miya keyingi fikrni rejalashtiradi, shuning uchun pauzani ham shu yerga qo‘ying.', 'Именно там мозг планирует следующую мысль — туда и ставьте паузу.']),
    item('f5', ['Someone asks a hard question. What is the best way to start your answer?', 'Kimdir qiyin savol berdi. Javobni qanday boshlash eng yaxshi?', 'Вам задали трудный вопрос. Как лучше начать ответ?'], [['"Ummm… well… so…"', '«Eee… xullas… haligi…»', '«Ну-у… значит… короче…»'], ['"Good question." [pause] Then the answer.', '«Yaxshi savol.» [pauza] Keyin javob.', '«Хороший вопрос». [пауза] Затем ответ.'], ['Start answering immediately with whatever comes.', 'Xayolga kelganini darhol gapira boshlang.', 'Сразу говорить всё, что придёт в голову.']], 1, ['A short phrase plus a pause buys thinking time without sounding lost.', 'Qisqa ibora va pauza o‘ylash uchun vaqt beradi va adashgandek eshitilmaydi.', 'Короткая фраза и пауза дают время подумать и не звучат растерянно.']),
    item('f6', ['Which is NOT a filler in a talk?', 'Nutqda qaysi biri to‘ldiruvchi so‘z EMAS?', 'Что в речи НЕ является словом-паразитом?'], [['"Um" before every sentence.', 'Har gap oldidan aytiladigan «ee».', '«Ну» перед каждой фразой.'], ['"For example" before a real example.', 'Haqiqiy misoldan oldingi «masalan».', '«Например» перед настоящим примером.'], ['"Like" with no meaning, again and again.', 'Ma’nosiz qayta-qayta takrorlanadigan «haligi».', 'Бессмысленное «как бы» снова и снова.']], 1, ['A word that does a job (introducing an example) is not a filler.', 'Vazifasi bor so‘z (misolni boshlab beradi) to‘ldiruvchi so‘z emas.', 'Слово, у которого есть задача (ввести пример), — не слово-паразит.']),
    item('f7', ['How can you practise this week?', 'Bu hafta qanday mashq qilishingiz mumkin?', 'Как потренироваться на этой неделе?'], [['Record a one-minute answer each day and count your fillers.', 'Har kuni bir daqiqalik javob yozib oling va to‘ldiruvchi so‘zlarni sanang.', 'Каждый день записывать минутный ответ и считать слова-паразиты.'], ['Never speak in public until the habit is gone.', 'Odat yo‘qolguncha odamlar oldida umuman gapirmang.', 'Не выступать вовсе, пока привычка не исчезнет.'], ['Ask a friend to clap loudly at every filler during your exam.', 'Imtihonda har bir to‘ldiruvchi so‘zda do‘stingiz qattiq qarsak chalsin.', 'Попросить друга громко хлопать на каждое слово-паразит прямо на экзамене.']], 0, ['Short daily recordings with a number to beat make progress you can see.', 'Har kungi qisqa yozuv va yaxshilash kerak bo‘lgan raqam o‘sishingizni ko‘rinadigan qiladi.', 'Короткие ежедневные записи с цифрой, которую нужно побить, дают видимый прогресс.']),
    item('f8', ['You notice you just said "like" three times. What now?', '«Haligi» so‘zini hozirgina uch marta aytganingizni sezdingiz. Endi nima?', 'Вы заметили, что сказали «типа» три раза подряд. Что теперь?'], [['Say "sorry for my fillers" to the audience.', 'Tinglovchilarga «to‘ldiruvchi so‘zlarim uchun uzr» deng.', 'Сказать залу: «Извините за слова-паразиты».'], ['Slow down for the next sentence and pause at its end.', 'Keyingi gapni sekinroq ayting va oxirida to‘xtang.', 'Замедлить следующую фразу и сделать паузу в её конце.'], ['Stop the talk and start again.', 'Nutqni to‘xtatib, qaytadan boshlang.', 'Остановить выступление и начать сначала.']], 1, ['Slowing down gives your brain time and the fillers fade; drawing attention to them does not help.', 'Sekinlashish miyaga vaqt beradi va to‘ldiruvchi so‘zlar kamayadi; ularga e’tibor qaratish foyda bermaydi.', 'Замедление даёт мозгу время, и слова-паразиты уходят; привлекать к ним внимание бесполезно.']),
  ]),
  drill('drill.pace', 'too_fast', 'delivery.pace', ['Find a pace people can follow', 'Tinglash oson bo‘lgan sur’at', 'Темп, за которым успевают'], ['A comfortable talk is about 110–170 words a minute. Nerves push most people faster. Slow down on numbers, names and your key sentence, and let each point end with a pause.', 'Qulay nutq sur’ati — daqiqasiga taxminan 110–170 so‘z. Hayajon ko‘pchilikni tezlashtiradi. Raqamlar, ismlar va asosiy gapda sekinlashing, har bir fikrni pauza bilan yakunlang.', 'Комфортный темп — примерно 110–170 слов в минуту. Волнение ускоряет большинство людей. Замедляйтесь на цифрах, именах и главной фразе, заканчивайте каждый тезис паузой.'], [
    item('pa1', ['Your talk was measured at 195 words per minute. What does it mean?', 'Nutqingiz daqiqasiga 195 so‘z deb o‘lchandi. Bu nimani anglatadi?', 'Ваш темп — 195 слов в минуту. Что это значит?'], [['Great energy; keep it.', 'Zo‘r energiya; shunday qoldiring.', 'Отличная энергия, так держать.'], ['Too fast for most listeners to follow; slow down on key lines.', 'Ko‘pchilik tinglovchilar uchun juda tez; asosiy gaplarda sekinlashing.', 'Слишком быстро для большинства слушателей; замедлитесь на главных фразах.'], ['Too slow; speed up.', 'Juda sekin; tezlashing.', 'Слишком медленно, ускорьтесь.']], 1, ['Above about 170 words a minute many listeners start to miss words, especially numbers.', 'Daqiqasiga taxminan 170 so‘zdan oshsa, ko‘p tinglovchilar so‘zlarni, ayniqsa raqamlarni o‘tkazib yubora boshlaydi.', 'Выше примерно 170 слов в минуту многие слушатели начинают пропускать слова, особенно цифры.']),
    item('pa2', ['Which part of a talk should be the slowest?', 'Nutqning qaysi qismi eng sekin bo‘lishi kerak?', 'Какая часть речи должна быть самой медленной?'], [['The greeting.', 'Salomlashish.', 'Приветствие.'], ['Your key message and any numbers.', 'Asosiy xabaringiz va raqamlar.', 'Главная мысль и все цифры.'], ['The examples.', 'Misollar.', 'Примеры.']], 1, ['Slow down where the listener must remember something.', 'Tinglovchi nimanidir eslab qolishi kerak bo‘lgan joyda sekinlashing.', 'Замедляйтесь там, где слушатель должен что-то запомнить.']),
    item('pa3', ['You are nervous and feel yourself speeding up. Best fix?', 'Hayajonlanib, tezlashayotganingizni sezyapsiz. Eng yaxshi yechim?', 'Вы волнуетесь и чувствуете, что ускоряетесь. Лучшее решение?'], [['Take one slow breath and pause at the end of the next sentence.', 'Bir marta sekin nafas oling va keyingi gap oxirida to‘xtang.', 'Сделать один медленный вдох и паузу в конце следующей фразы.'], ['Skip parts of the talk to finish sooner.', 'Tezroq tugatish uchun nutqning bir qismini tashlab keting.', 'Пропустить части речи, чтобы закончить быстрее.'], ['Speak louder.', 'Balandroq gapiring.', 'Говорить громче.']], 0, ['A breath and a pause reset the pace without the audience noticing.', 'Nafas va pauza sur’atni tinglovchi sezmagan holda tiklaydi.', 'Вдох и пауза сбрасывают темп незаметно для зала.']),
    item('pa4', ['How do you say "Our sales grew by 37 percent" so people catch it?', '«Savdomiz 37 foizga oshdi» gapini odamlar ilg‘ab olishi uchun qanday aytasiz?', 'Как сказать «Продажи выросли на 37 процентов», чтобы это услышали?'], [['Quickly, as part of a longer sentence.', 'Tez, uzunroq gap ichida.', 'Быстро, внутри длинной фразы.'], ['Slowly, with a short pause before "37 percent".', 'Sekin, «37 foiz»dan oldin qisqa pauza bilan.', 'Медленно, с короткой паузой перед «37 процентов».'], ['Only on the slide, without saying it.', 'Aytmasdan, faqat slaydda.', 'Только на слайде, не произнося.']], 1, ['Numbers need space; a pause before them signals "this matters".', 'Raqamlarga joy kerak; ulardan oldingi pauza «bu muhim» degan ishora.', 'Цифрам нужно место; пауза перед ними говорит «это важно».']),
    item('pa5', ['Your pace is 85 words per minute with many long pauses. What is likely?', 'Sur’atingiz daqiqasiga 85 so‘z, uzun pauzalar ko‘p. Ehtimol nima bo‘lgan?', 'Ваш темп — 85 слов в минуту и много длинных пауз. Что вероятнее всего?'], [['You were searching for words; plan your points before you speak.', 'So‘z qidirgansiz; gapirishdan oldin fikrlaringizni rejalashtiring.', 'Вы искали слова; продумывайте тезисы до начала речи.'], ['It is the perfect pace.', 'Bu ideal sur’at.', 'Это идеальный темп.'], ['You spoke too fast.', 'Juda tez gapirgansiz.', 'Вы говорили слишком быстро.']], 0, ['Very slow with many long pauses usually means searching; a plan of three points fixes it.', 'Juda sekin va ko‘p uzun pauza odatda qidiruvni bildiradi; uchta fikrdan iborat reja buni tuzatadi.', 'Очень медленно и много пауз — обычно признак поиска; план из трёх тезисов помогает.']),
    item('pa6', ['What helps you keep a steady pace in a long presentation?', 'Uzun taqdimotda bir maromdagi sur’atni saqlashga nima yordam beradi?', 'Что помогает держать ровный темп в длинной презентации?'], [['Short sentences with a pause after each point.', 'Qisqa gaplar va har bir fikrdan keyin pauza.', 'Короткие фразы и пауза после каждого тезиса.'], ['Reading long paragraphs from the slide.', 'Slayddan uzun abzaslarni o‘qish.', 'Чтение длинных абзацев со слайда.'], ['Drinking coffee before you start.', 'Boshlashdan oldin qahva ichish.', 'Выпить кофе перед началом.']], 0, ['Short sentences set a natural rhythm; reading long text speeds most people up.', 'Qisqa gaplar tabiiy ritm yaratadi; uzun matnni o‘qish ko‘pchilikni tezlashtiradi.', 'Короткие фразы задают естественный ритм, а при чтении длинного текста большинство людей ускоряется.']),
    item('pa7', ['Which talk is easiest to follow?', 'Qaysi nutqni tinglash eng oson?', 'За какой речью легче всего следить?'], [['The same fast pace all the way.', 'Boshidan oxirigacha bir xil tez sur’at.', 'Один и тот же быстрый темп всё время.'], ['A varied pace: a little faster for stories, slower for key points.', 'O‘zgaruvchan sur’at: hikoyada biroz tezroq, asosiy fikrlarda sekinroq.', 'Переменный темп: чуть быстрее в истории, медленнее на главном.'], ['The same slow pace all the way.', 'Boshidan oxirigacha bir xil sekin sur’at.', 'Один и тот же медленный темп всё время.']], 1, ['Changing pace on purpose keeps attention and marks what matters.', 'Sur’atni ataylab o‘zgartirish diqqatni ushlab turadi va muhim joyni belgilaydi.', 'Намеренная смена темпа держит внимание и выделяет важное.']),
    item('pa8', ['You have five minutes but material for ten. What do you do?', 'Sizda besh daqiqa bor, lekin material o‘n daqiqalik. Nima qilasiz?', 'У вас пять минут, а материала на десять. Что делать?'], [['Speak twice as fast.', 'Ikki baravar tez gapiring.', 'Говорить вдвое быстрее.'], ['Cut to your two strongest points and keep a normal pace.', 'Eng kuchli ikkita fikrni qoldiring va oddiy sur’atda gapiring.', 'Оставить два сильнейших тезиса и говорить в обычном темпе.'], ['Ask for more time at the end.', 'Oxirida qo‘shimcha vaqt so‘rang.', 'Попросить больше времени в конце.']], 1, ['Cut content, not pace: people remember two clear points, not ten rushed ones.', 'Sur’atni emas, mazmunni qisqartiring: odamlar shoshib aytilgan o‘nta fikrni emas, ikkita aniq fikrni eslab qoladi.', 'Сокращайте содержание, а не темп: запомнят два ясных тезиса, а не десять скомканных.']),
  ]),
  drill('drill.pauses', 'no_pauses', 'delivery.pauses', ['Use pauses on purpose', 'Pauzadan ataylab foydalaning', 'Паузы с умыслом'], ['A deliberate pause before a key idea makes people lean in; a pause after a question lets them think; a pause between points shows the structure. One to two seconds is enough.', 'Asosiy fikrdan oldingi ataylab qilingan pauza odamlarni diqqat qilishga undaydi; savoldan keyingi pauza o‘ylashga imkon beradi; fikrlar orasidagi pauza tuzilmani ko‘rsatadi. Bir-ikki soniya yetarli.', 'Намеренная пауза перед главной мыслью заставляет прислушаться; после вопроса — даёт подумать; между тезисами — показывает структуру. Одной-двух секунд достаточно.'], [
    item('pz1', ['Where is a pause most powerful?', 'Pauza qayerda eng kuchli ta’sir qiladi?', 'Где пауза работает сильнее всего?'], [['Right before your key message.', 'Asosiy xabaringizdan darhol oldin.', 'Прямо перед главной мыслью.'], ['In the middle of a name.', 'Ism o‘rtasida.', 'Посреди имени.'], ['After every single word.', 'Har bir so‘zdan keyin.', 'После каждого слова.']], 0, ['A pause before the key line tells the audience: listen now.', 'Asosiy gapdan oldingi pauza tinglovchiga: hozir quloq soling, deydi.', 'Пауза перед главной фразой говорит залу: слушайте сейчас.']),
    item('pz2', ['You ask the audience: "Who has felt this?" What next?', 'Auditoriyadan so‘radingiz: «Bu tuyg‘u kimga tanish?» Keyin-chi?', 'Вы спрашиваете зал: «Кому знакомо это чувство?» Что дальше?'], [['Answer it yourself immediately.', 'Darhol o‘zingiz javob bering.', 'Сразу ответить самому.'], ['Wait two seconds and look at the room.', 'Ikki soniya kuting va zalga qarang.', 'Подождать две секунды и посмотреть на зал.'], ['Ask another question at once.', 'Darhol boshqa savol bering.', 'Сразу задать другой вопрос.']], 1, ['The silence lets people actually think, which makes the question work.', 'Jimlik odamlarga haqiqatan o‘ylashga imkon beradi va savol o‘z ishini qiladi.', 'Тишина даёт людям подумать — и вопрос срабатывает.']),
    item('pz3', ['How long should a deliberate pause be?', 'Ataylab qilingan pauza qancha davom etishi kerak?', 'Сколько должна длиться намеренная пауза?'], [['About one to two seconds.', 'Taxminan bir-ikki soniya.', 'Примерно одну-две секунды.'], ['Ten seconds.', 'O‘n soniya.', 'Десять секунд.'], ['As short as possible, never noticeable.', 'Iloji boricha qisqa, sezilmaydigan.', 'Как можно короче, чтобы никто не заметил.']], 0, ['It feels long to you but sounds natural and confident to the room.', 'Sizga uzun tuyuladi, lekin tinglovchiga tabiiy va ishonchli eshitiladi.', 'Вам кажется долго, а залу — естественно и уверенно.']),
    item('pz4', ['Which sounds better when moving to your second point?', 'Ikkinchi fikrga o‘tishda qaysi biri yaxshiroq eshitiladi?', 'Что звучит лучше при переходе ко второму тезису?'], [['"…and also, and then, another thing is…"', '«…va yana, keyin, yana bir narsa…»', '«…и ещё, и потом, ещё одно…»'], ['A pause, then: "My second point."', 'Pauza, keyin: «Ikkinchi fikrim.»', 'Пауза, затем: «Мой второй тезис».'], ['No break at all, to save time.', 'Vaqt tejash uchun umuman to‘xtamaslik.', 'Без перерыва, чтобы сэкономить время.']], 1, ['The pause closes the first point; the signpost opens the next.', 'Pauza birinchi fikrni yopadi, o‘tish iborasi esa keyingisini ochadi.', 'Пауза закрывает первый тезис, связка открывает следующий.']),
    item('pz5', ['A long pause that is NOT helpful is…', 'Foydali BO‘LMAGAN uzun pauza — bu…', 'Длинная пауза, которая НЕ помогает, — это…'], [['…a pause before a surprising number.', '…kutilmagan raqamdan oldingi pauza.', '…пауза перед удивительной цифрой.'], ['…a pause in the middle of a sentence while you search for a basic word.', '…oddiy so‘zni qidirib, gap o‘rtasida qilingan pauza.', '…пауза посреди фразы, пока вы ищете простое слово.'], ['…a pause after a question to the audience.', '…auditoriyaga savoldan keyingi pauza.', '…пауза после вопроса залу.']], 1, ['Pauses while you search for a word break the sentence; plan your points so pauses fall at the ends of sentences.', 'So‘z qidirib qilingan pauza gapni bo‘lib yuboradi; pauzalar gap oxiriga tushishi uchun fikrlaringizni oldindan rejalashtiring.', 'Паузы, пока вы ищете слово, рвут фразу; продумайте тезисы заранее, чтобы паузы приходились на конец фразы.']),
    item('pz6', ['How can you remember to pause in a rehearsal?', 'Repetitsiyada pauza qilishni qanday eslab qolasiz?', 'Как не забыть паузы на репетиции?'], [['Mark a slash (/) in your notes where each pause goes.', 'Eslatmalaringizda pauza qilinadigan joylarga (/) belgisini qo‘ying.', 'Ставить в заметках косую черту (/) там, где нужна пауза.'], ['Hope it happens naturally.', 'O‘z-o‘zidan bo‘lishiga umid qiling.', 'Надеяться, что получится само.'], ['Count to five after every sentence.', 'Har gapdan keyin beshgacha sanang.', 'Считать до пяти после каждой фразы.']], 0, ['A simple mark in your notes turns pauses into a habit.', 'Eslatmadagi oddiy belgi pauzani odatga aylantiradi.', 'Простая пометка в заметках превращает паузы в привычку.']),
    item('pz7', ['You just told the most emotional moment of your story. What next?', 'Hikoyangizning eng ta’sirli lahzasini aytdingiz. Keyin-chi?', 'Вы рассказали самый эмоциональный момент истории. Что дальше?'], [['Rush to the next part before it gets awkward.', 'Noqulay bo‘lmasligi uchun keyingi qismga shoshiling.', 'Скорее перейти дальше, пока не стало неловко.'], ['Let it land with a short pause.', 'Qisqa pauza qiling, u tinglovchiga yetib borsin.', 'Выдержать короткую паузу, чтобы момент прозвучал.'], ['Make a joke immediately.', 'Darhol hazil qiling.', 'Сразу пошутить.']], 1, ['A pause gives the audience a moment to feel it.', 'Pauza tinglovchiga uni his qilish uchun lahza beradi.', 'Пауза даёт залу момент это почувствовать.']),
    item('pz8', ['Which opening uses a pause well?', 'Qaysi boshlanishda pauza yaxshi ishlatilgan?', 'В каком начале пауза использована хорошо?'], [['Walk up, look at the room for a second, then start.', 'Sahnaga chiqing, bir soniya zalga qarang, keyin boshlang.', 'Выйти, секунду посмотреть на зал и начать.'], ['Start talking while you are still walking up.', 'Sahnaga chiqib kelayotib gapira boshlang.', 'Начать говорить ещё по дороге к сцене.'], ['Say "ee, so, OK" until people go quiet.', 'Odamlar jim bo‘lguncha «ee, xullas, xo‘p» deng.', 'Говорить «ну, так, ладно», пока все не затихнут.']], 0, ['One silent second at the start gathers attention better than any word.', 'Boshlanishdagi bir soniyalik jimlik har qanday so‘zdan yaxshiroq diqqat yig‘adi.', 'Секунда тишины в начале собирает внимание лучше любых слов.']),
  ]),
  drill('drill.hook', 'no_hook', 'structure.hook', ['Openings that hook', 'Diqqatni tortuvchi kirish', 'Начало с зацепкой'], ['Your first two sentences decide whether people listen. Open with a question, a true surprising fact, a short story or a picture in words — and save "my name is" and the title for a moment later.', 'Dastlabki ikki gap odamlar tinglaydimi-yo‘qmi, shuni hal qiladi. Savol, haqiqiy qiziq fakt, qisqa hikoya yoki so‘z bilan chizilgan manzara bilan boshlang — «ismim…» va mavzu nomini keyinroq ayting.', 'Первые две фразы решают, будут ли вас слушать. Начните с вопроса, удивительного правдивого факта, короткой истории или картинки, нарисованной словами, — а «меня зовут» и название темы оставьте на потом.'], [
    item('h1', ['A talk about saving water. Which opening is best?', 'Suvni tejash haqida nutq. Qaysi kirish eng yaxshi?', 'Речь об экономии воды. Какое начало лучше?'], [['Today I will talk about water.', 'Bugun men suv haqida gapiraman.', 'Сегодня я расскажу о воде.'], ['How many glasses of water did you waste this morning while brushing your teeth?', 'Bugun ertalab tish yuvayotganda necha stakan suvni isrof qildingiz?', 'Сколько стаканов воды вы потратили впустую сегодня утром, пока чистили зубы?'], ['Water is very important for everybody.', 'Suv hamma uchun juda muhim.', 'Вода очень важна для всех.']], 1, ['A personal question pulls each listener into the topic at once.', 'Shaxsiy savol har bir tinglovchini darhol mavzuga tortadi.', 'Личный вопрос сразу вовлекает каждого слушателя.']),
    item('h2', ['Which is a story hook?', 'Qaysi biri hikoyali kirish?', 'Какое начало построено на истории?'], [['Last winter, at six in the morning, our bus did not come.', 'O‘tgan qishda, ertalab soat oltida avtobusimiz kelmadi.', 'Прошлой зимой, в шесть утра, наш автобус не пришёл.'], ['Transport is a big problem in many cities.', 'Transport ko‘p shaharlarda katta muammo.', 'Транспорт — большая проблема во многих городах.'], ['I want to thank the organisers.', 'Tashkilotchilarga rahmat aytmoqchiman.', 'Хочу поблагодарить организаторов.']], 0, ['Time, place and a problem in one sentence: the audience wants to know what happened.', 'Bir gapda vaqt, joy va muammo: tinglovchi nima bo‘lganini bilmoqchi bo‘ladi.', 'Время, место и проблема в одной фразе — зал хочет знать, что было дальше.']),
    item('h3', ['You want to open with a number. Which is right?', 'Raqam bilan boshlamoqchisiz. Qaysi biri to‘g‘ri?', 'Вы хотите начать с цифры. Как правильно?'], [['Use a number you know is true, and say where it comes from.', 'Haqiqatligini biladigan raqamni ishlating va manbasini ayting.', 'Используйте цифру, в которой уверены, и назовите источник.'], ['Make up a big number; it sounds impressive.', 'Katta raqam o‘ylab toping; ta’sirli eshitiladi.', 'Придумайте большую цифру — звучит впечатляюще.'], ['Say "studies show" without saying which.', 'Qaysi ekanini aytmasdan «tadqiqotlar ko‘rsatadi» deng.', 'Скажите «исследования показывают», не уточняя какие.']], 0, ['A hook must be true; one invented number can lose the whole room.', 'Kirish haqiqatga asoslanishi kerak; bitta to‘qima raqam butun zalning ishonchini yo‘qotishi mumkin.', 'Зацепка должна быть правдой: одна выдуманная цифра может стоить доверия всего зала.']),
    item('h4', ['A pitch to a jury. Which first line is strongest?', 'Hakamlarga taqdimot. Qaysi birinchi gap eng kuchli?', 'Питч перед жюри. Какая первая фраза сильнее?'], [['Hello, my name is Aziz and I am a student.', 'Assalomu alaykum, ismim Aziz, men talabaman.', 'Здравствуйте, меня зовут Азиз, я студент.'], ['Every day, farmers at our bazaar throw away vegetables nobody bought.', 'Har kuni bozorimizdagi fermerlar hech kim sotib olmagan sabzavotlarni tashlab yuboradi.', 'Каждый день фермеры на нашем базаре выбрасывают овощи, которые никто не купил.'], ['Thank you for this opportunity.', 'Bu imkoniyat uchun rahmat.', 'Спасибо за эту возможность.']], 1, ['Lead with the problem; your name can come in the second sentence.', 'Muammo bilan boshlang; ismingizni ikkinchi gapda aytsangiz bo‘ladi.', 'Начните с проблемы; имя можно назвать во второй фразе.']),
    item('h5', ['Which opening "paints a picture"?', 'Qaysi kirish «manzara chizadi»?', 'Какое начало «рисует картинку»?'], [['Imagine a classroom where every student has their hand up.', 'Har bir o‘quvchi qo‘l ko‘targan sinfxonani tasavvur qiling.', 'Представьте класс, где каждый ученик тянет руку.'], ['Education is important for our future.', 'Ta’lim kelajagimiz uchun muhim.', 'Образование важно для нашего будущего.'], ['I am going to present my project.', 'Men loyihamni taqdim etaman.', 'Я представлю свой проект.']], 0, ['"Imagine…" gives the audience a scene to see in their heads.', '«Tasavvur qiling…» tinglovchiga ko‘z oldiga keltiradigan manzara beradi.', '«Представьте…» даёт залу сцену, которую можно увидеть.']),
    item('h6', ['How long should the hook be?', 'Kirish qancha uzun bo‘lishi kerak?', 'Какой длины должна быть зацепка?'], [['One or two sentences, then move on to your point.', 'Bir-ikki gap, keyin fikringizga o‘ting.', 'Одна-две фразы, затем переходите к сути.'], ['At least half the talk.', 'Nutqning kamida yarmi.', 'Не меньше половины речи.'], ['There is no need for a hook.', 'Kirish shart emas.', 'Зацепка не нужна.']], 0, ['A hook opens the door; then you walk through it to your message.', 'Kirish eshikni ochadi, keyin u orqali xabaringizga o‘tasiz.', 'Зацепка открывает дверь, дальше вы ведёте к своей мысли.']),
    item('h7', ['After the hook, what should come next?', 'Kirishdan keyin nima kelishi kerak?', 'Что должно идти после зацепки?'], [['Why it matters to them and what you will cover.', 'Bu ular uchun nega muhim va nimalar haqida gapirishingiz.', 'Почему это важно слушателям и о чём вы расскажете.'], ['A long history of the topic.', 'Mavzuning uzun tarixi.', 'Долгая история темы.'], ['An apology for being nervous.', 'Hayajon uchun uzr.', 'Извинение за волнение.']], 0, ['Connect the hook to the listener, then give a short map of your points.', 'Kirishni tinglovchiga bog‘lang, keyin fikrlaringizning qisqa xaritasini bering.', 'Свяжите зацепку со слушателем и дайте короткую карту тезисов.']),
    item('h8', ['A school assembly about kindness. Best hook?', 'Mehribonlik haqida maktab yig‘ilishi. Eng yaxshi kirish?', 'Школьная линейка о доброте. Лучшее начало?'], [['Kindness is a very good quality.', 'Mehribonlik juda yaxshi fazilat.', 'Доброта — очень хорошее качество.'], ['Yesterday a boy in fifth grade gave his only pen to a new classmate.', 'Kecha beshinchi sinfdagi bir bola yagona ruchkasini yangi sinfdoshiga berdi.', 'Вчера мальчик из пятого класса отдал свою единственную ручку новенькому.'], ['Let me read the definition of kindness.', 'Keling, mehribonlik ta’rifini o‘qib beraman.', 'Позвольте прочитать определение доброты.']], 1, ['A real small moment from your school beats any definition.', 'Maktabingizdagi haqiqiy kichik lahza har qanday ta’rifdan ustun.', 'Реальный маленький эпизод из школы лучше любого определения.']),
  ]),
  drill('drill.close', 'no_close', 'structure.close', ['Closes that land', 'Ta’sirli yakun', 'Финал, который запоминается'], ['End on purpose: one line that sums up your message and one clear request. Practise the last sentence until you can say it without notes, then stop and smile.', 'Ataylab yakunlang: xabaringizni jamlovchi bitta gap va bitta aniq iltimos. Oxirgi gapni eslatmasiz ayta olguningizcha mashq qiling, keyin to‘xtang va tabassum qiling.', 'Заканчивайте намеренно: одна фраза-итог и одна ясная просьба. Репетируйте последнюю фразу, пока не сможете сказать её без заметок, затем остановитесь и улыбнитесь.'], [
    item('c1', ['Which is the best last line?', 'Qaysi biri eng yaxshi oxirgi gap?', 'Какая последняя фраза лучше всего?'], [['So, that’s all, I think.', 'Xullas, shu, shekilli.', 'Ну вот, вроде всё.'], ['Join us on Saturday at nine: one morning, one cleaner canal.', 'Shanba kuni soat to‘qqizda bizga qo‘shiling: bitta tong, bitta tozaroq kanal.', 'Присоединяйтесь в субботу в девять: одно утро — и канал станет чище.'], ['Sorry if it was too long.', 'Uzun bo‘lgan bo‘lsa, kechirasiz.', 'Извините, если было долго.']], 1, ['A specific request with a day and a time, said as a memorable line.', 'Kun va vaqt ko‘rsatilgan aniq iltimos, eslab qolinadigan gap shaklida.', 'Конкретная просьба с днём и временем, сказанная запоминающейся фразой.']),
    item('c2', ['What is a call to action?', 'Harakatga chaqiriq nima?', 'Что такое призыв к действию?'], [['A clear thing you ask the audience to think, feel or do.', 'Tinglovchilardan aniq bir narsani o‘ylash, his qilish yoki qilishni so‘rash.', 'Ясная просьба к залу: что подумать, почувствовать или сделать.'], ['A summary of all your slides.', 'Barcha slaydlaringizning xulosasi.', 'Пересказ всех слайдов.'], ['A thank-you to the organisers.', 'Tashkilotchilarga minnatdorchilik.', 'Благодарность организаторам.']], 0, ['Without a request, people agree and then do nothing.', 'Iltimos bo‘lmasa, odamlar rozi bo‘ladi va hech narsa qilmaydi.', 'Без просьбы люди соглашаются — и ничего не делают.']),
    item('c3', ['You ran out of time. What do you do?', 'Vaqtingiz tugadi. Nima qilasiz?', 'У вас закончилось время. Что делать?'], [['Stop in the middle and leave.', 'Gap o‘rtasida to‘xtab, chiqib keting.', 'Остановиться на полуслове и уйти.'], ['Skip to your prepared last two sentences.', 'Tayyorlangan oxirgi ikki gapingizga o‘ting.', 'Перейти к заготовленным последним двум фразам.'], ['Ask for ten more minutes.', 'Yana o‘n daqiqa so‘rang.', 'Попросить ещё десять минут.']], 1, ['Always protect the close: it is what people remember.', 'Yakunga doim vaqt qoldiring: odamlar aynan uni eslab qoladi.', 'Всегда оставляйте время на финал — именно его запоминают.']),
    item('c4', ['Which close brings the talk full circle?', 'Qaysi yakun nutqni boshiga qaytaradi?', 'Какой финал замыкает круг?'], [['Returning to the person from your opening story.', 'Kirish hikoyangizdagi insonga qaytish.', 'Вернуться к герою истории из начала.'], ['Adding a new topic at the end.', 'Oxirida yangi mavzu qo‘shish.', 'Добавить в конце новую тему.'], ['Reading the agenda again.', 'Kun tartibini qayta o‘qish.', 'Снова зачитать план.']], 0, ['Coming back to the opening ties the talk together and feels complete.', 'Kirishga qaytish nutqni bir butun qiladi va u tugallangandek tuyuladi.', 'Возврат к началу связывает речь и даёт ощущение завершённости.']),
    item('c5', ['How should you deliver the last sentence?', 'Oxirgi gapni qanday aytish kerak?', 'Как произнести последнюю фразу?'], [['Slowly, looking at the audience, then pause.', 'Sekin, auditoriyaga qarab, keyin to‘xtab.', 'Медленно, глядя в зал, затем пауза.'], ['Quickly while walking off.', 'Tez, chiqib ketayotib.', 'Быстро, уходя со сцены.'], ['Reading it from your phone.', 'Telefoningizdan o‘qib.', 'Читая с телефона.']], 0, ['Slow, eyes up, then a pause: the line lands.', 'Sekin, ko‘zlar tinglovchida, keyin pauza: gap o‘z ta’sirini qiladi.', 'Медленно, глаза в зал, пауза — и фраза попадает в цель.']),
    item('c6', ['A pitch to an investor. Which close is best?', 'Investorga taqdimot. Qaysi yakun eng yaxshi?', 'Питч инвестору. Какой финал лучше?'], [['Could we meet next week for thirty minutes to show you the first results?', 'Keyingi hafta o‘ttiz daqiqaga uchrashib, birinchi natijalarni ko‘rsatsak bo‘ladimi?', 'Сможем встретиться на следующей неделе на полчаса? Я покажу первые результаты.'], ['We hope you like our idea.', 'G‘oyamiz sizga yoqdi degan umiddamiz.', 'Надеемся, вам понравилась наша идея.'], ['Any questions? No? OK.', 'Savollar bormi? Yo‘qmi? Xo‘p.', 'Вопросы есть? Нет? Ладно.']], 0, ['A small, specific next step is easy to say yes to.', 'Kichik, aniq keyingi qadamga «ha» deyish oson.', 'На маленький конкретный шаг легко сказать «да».']),
    item('c7', ['Should your last words be "Any questions?"', 'Oxirgi so‘zlaringiz «Savollar bormi?» bo‘lishi kerakmi?', 'Стоит ли заканчивать словами «Есть вопросы?»'], [['Yes, always end there.', 'Ha, doim shu bilan yakunlang.', 'Да, всегда заканчивайте так.'], ['No: after the Q&A, finish again with your key line.', 'Yo‘q: savol-javobdan keyin asosiy gapingiz bilan yana yakunlang.', 'Нет: после вопросов ещё раз закончите главной фразой.'], ['It does not matter.', 'Farqi yo‘q.', 'Это неважно.']], 1, ['Questions can end weakly; a final key line puts your message last.', 'Savol-javob sust tugashi mumkin; yakuniy asosiy gap esa xabaringizni eng oxirida yangratadi.', 'Вопросы могут закончиться вяло; финальная главная фраза оставляет последнее слово за вашей мыслью.']),
    item('c8', ['Which is a summary line?', 'Qaysi biri jamlovchi gap?', 'Какая фраза — итоговая?'], [['Small steps, every day, together: that is how this school changes.', 'Kichik qadamlar, har kuni, birgalikda: bu maktab shunday o‘zgaradi.', 'Маленькие шаги, каждый день, вместе — так меняется эта школа.'], ['I have many more slides but no time.', 'Yana ko‘p slaydlarim bor, lekin vaqt yo‘q.', 'У меня ещё много слайдов, но нет времени.'], ['I think I said everything.', 'Hammasini aytdim shekilli.', 'Кажется, это всё.']], 0, ['It repeats the message in a rhythm of three that sticks.', 'U xabarni yodda qoladigan uchlik ritmda takrorlaydi.', 'Она повторяет мысль в запоминающемся ритме из трёх частей.']),
  ]),
  drill('drill.signposts', 'rambling', 'structure.points', ['Signposts that keep people with you', 'Tinglovchini ushlab turadigan o‘tish iboralari', 'Связки, которые держат внимание'], ['Give the listener a map and use it: announce how many points, number them, and close each one before the next. If a point has no example, cut it.', 'Tinglovchiga xarita bering va undan foydalaning: nechta fikr borligini e’lon qiling, ularni sanang, keyingisidan oldin har birini yakunlang. Misoli yo‘q fikrni olib tashlang.', 'Дайте слушателю карту и следуйте ей: объявите число тезисов, нумеруйте их, закрывайте каждый перед следующим. Тезис без примера — уберите.'], [
    item('r1', ['Which sentence gives the audience a map?', 'Qaysi gap auditoriyaga xarita beradi?', 'Какая фраза даёт залу карту?'], [['I will cover three things: the problem, the plan, and what we need.', 'Uchta narsa haqida gapiraman: muammo, reja va bizga nima kerakligi.', 'Я расскажу о трёх вещах: о проблеме, о плане и о том, что нам нужно.'], ['I will say many things today.', 'Bugun ko‘p narsa aytaman.', 'Сегодня я скажу много всего.'], ['Let us start and see where we go.', 'Boshlaymiz-u, qayerga borishimizni ko‘ramiz.', 'Начнём, а там посмотрим.']], 0, ['Three named parts tell people where you are going.', 'Nomlangan uchta qism odamlarga qayerga borayotganingizni aytadi.', 'Три названные части показывают, куда вы ведёте.']),
    item('r2', ['You realise you are on a side story. What now?', 'Chetga chiqib ketganingizni sezdingiz. Endi nima?', 'Вы поняли, что ушли в сторону. Что теперь?'], [['Keep going; it might connect later.', 'Davom eting; keyinroq bog‘lanib qolar.', 'Продолжать — может, позже свяжется.'], ['Say "Back to my second point" and continue.', '«Ikkinchi fikrimga qaytsak» deng va davom eting.', 'Сказать «Вернёмся ко второму тезису» и продолжить.'], ['Apologise and start again.', 'Uzr so‘rang va qaytadan boshlang.', 'Извиниться и начать заново.']], 1, ['A signpost brings everyone back without drama.', 'O‘tish iborasi hammani shov-shuvsiz mavzuga qaytaradi.', 'Связка возвращает всех без драмы.']),
    item('r3', ['How many main points fit in a three-minute talk?', 'Uch daqiqalik nutqqa nechta asosiy fikr sig‘adi?', 'Сколько главных тезисов помещается в трёхминутную речь?'], [['Two or three.', 'Ikki yoki uchta.', 'Два-три.'], ['Seven or eight.', 'Yetti yoki sakkizta.', 'Семь-восемь.'], ['As many as possible.', 'Iloji boricha ko‘p.', 'Как можно больше.']], 0, ['Each point needs time for an example; more points means none land.', 'Har bir fikrga misol uchun vaqt kerak; ko‘p fikr — hech biri ta’sir qilmaydi.', 'Каждому тезису нужно время на пример; больше тезисов — ни один не запомнится.']),
    item('r4', ['Which is a good transition?', 'Qaysi biri yaxshi o‘tish?', 'Какой переход хороший?'], [['That is the problem. So what can we do about it?', 'Muammo shu. Xo‘sh, bu borada nima qila olamiz?', 'Вот в чём проблема. Что же мы можем с этим сделать?'], ['And, and also, and then…', 'Va, va yana, keyin…', 'И, и ещё, и потом…'], ['Next slide please.', 'Keyingi slayd, iltimos.', 'Следующий слайд, пожалуйста.']], 0, ['It closes one part and opens the next with a question.', 'U bir qismni yopadi va savol bilan keyingisini ochadi.', 'Он закрывает одну часть и открывает следующую вопросом.']),
    item('r5', ['A friend says your talk was "hard to follow". The most likely fix?', 'Do‘stingiz nutqingizni «tushunish qiyin» dedi. Nima ko‘proq yordam beradi?', 'Друг говорит, что за речью «трудно следить». Что, скорее всего, поможет?'], [['Number your points out loud.', 'Fikrlaringizni ovoz chiqarib sanang.', 'Вслух нумеровать тезисы.'], ['Speak louder.', 'Balandroq gapiring.', 'Говорить громче.'], ['Add more facts to each point.', 'Har bir fikrga ko‘proq fakt qo‘shing.', 'Добавить больше фактов в каждый тезис.']], 0, ['Spoken numbers (first, second) are the listener’s headings.', 'Og‘zaki raqamlar (birinchidan, ikkinchidan) tinglovchi uchun sarlavha.', 'Произнесённые номера («во-первых», «во-вторых») — заголовки для слуха.']),
    item('r6', ['Which plan is clearest for an impromptu answer?', 'Tayyorgarliksiz javob uchun qaysi reja eng aniq?', 'Какой план яснее всего для импровизации?'], [['Position, reason, example, position again.', 'Pozitsiya, sabab, misol, yana pozitsiya.', 'Позиция, причина, пример, снова позиция.'], ['Everything you know about the topic.', 'Mavzu haqida bilganlaringizning hammasi.', 'Всё, что вы знаете о теме.'], ['A list of facts in any order.', 'Har qanday tartibdagi faktlar ro‘yxati.', 'Список фактов в любом порядке.']], 0, ['A short formula keeps a one-minute answer clear under pressure.', 'Qisqa formula bir daqiqalik javobni bosim ostida ham aniq saqlaydi.', 'Короткая формула держит минутный ответ ясным даже под давлением.']),
    item('r7', ['You said "I have three reasons" but only gave two. What happens?', '«Uchta sababim bor» dedingiz, lekin ikkitasini aytdingiz. Nima bo‘ladi?', 'Вы сказали «у меня три причины», а назвали две. Что будет?'], [['People wait for the third and feel the talk is unfinished.', 'Odamlar uchinchisini kutadi va nutq tugallanmagandek tuyuladi.', 'Люди ждут третью и чувствуют, что речь не закончена.'], ['Nobody notices.', 'Hech kim sezmaydi.', 'Никто не заметит.'], ['It makes the talk shorter, which is good.', 'Nutq qisqaradi, bu yaxshi.', 'Речь становится короче — это хорошо.']], 0, ['Keep your map honest: if you promise three, deliver three.', 'Xaritangizga sodiq bo‘ling: uchta va’da qilsangiz, uchta ayting.', 'Будьте верны карте: обещали три — дайте три.']),
    item('r8', ['Which shows a point is finished?', 'Fikr tugaganini qaysi biri ko‘rsatadi?', 'Что показывает, что тезис завершён?'], [['A one-line summary, then a pause.', 'Bir gaplik xulosa, keyin pauza.', 'Итог в одну фразу, затем пауза.'], ['Talking faster.', 'Tezroq gapirish.', 'Говорить быстрее.'], ['Saying "etcetera, etcetera".', '«Va hokazo, va hokazo» deyish.', 'Сказать «и так далее, и так далее».']], 0, ['A mini-summary and a pause are full stops for the ear.', 'Kichik xulosa va pauza quloq uchun nuqta vazifasini bajaradi.', 'Мини-итог и пауза — это точки для слуха.']),
  ]),
  drill('drill.voice', 'monotone', 'delivery.voice', ['Bring your voice to life', 'Ovozingizni jonlantiring', 'Оживите голос'], ['Voice and intonation need the sound itself, so the coach never scores them from text. These drills teach the moves: stress one key word per sentence, let your voice rise on a yes/no question, slow down for important lines, and speak from notes rather than a full script.', 'Ovoz va ohangni faqat tovush orqali baholash mumkin, shuning uchun murabbiy ularni matndan baholamaydi. Bu mashqlar usullarni o‘rgatadi: har gapda bitta kalit so‘zni ovoz bilan ajratish (mantiqiy urg‘u), «ha/yo‘q» savolida ohangni ko‘tarish, muhim gapda sekinlashish va to‘liq matn o‘rniga eslatmadan gapirish.', 'Голос и интонацию можно оценить только на слух, поэтому коуч не оценивает их по тексту. Эти упражнения учат приёмам: выделение голосом одного ключевого слова во фразе, подъём тона в вопросе «да или нет», замедление на важном и речь по тезисам, а не по полному тексту.'], [
    item('v1', ['Why do talks read from paper often sound flat?', 'Nega qog‘ozdan o‘qilgan nutqlar ko‘pincha jonsiz eshitiladi?', 'Почему речь по бумажке часто звучит плоско?'], [['Reading uses written sentences and the eyes leave the audience.', 'O‘qishda yozma gaplar ishlatiladi va ko‘zlar tinglovchidan uziladi.', 'При чтении используются письменные фразы, а глаза уходят от зала.'], ['Paper absorbs sound.', 'Qog‘oz tovushni yutadi.', 'Бумага поглощает звук.'], ['Because the talk is too short.', 'Chunki nutq juda qisqa.', 'Потому что речь слишком короткая.']], 0, ['Speak from a few keywords so your voice follows your thoughts.', 'Ovozingiz fikringizga ergashishi uchun bir nechta kalit so‘zdan foydalanib gapiring.', 'Говорите по нескольким ключевым словам — голос пойдёт за мыслью.']),
    item('v2', ['In "We need ten volunteers", which word should you stress?', '«Bizga o‘nta ko‘ngilli kerak» gapida qaysi so‘zga urg‘u berish kerak?', 'Какое слово выделить во фразе «Нам нужно десять волонтёров»?'], [['ten', 'o‘nta', 'десять'], ['we', 'bizga', 'нам'], ['need', 'kerak', 'нужно']], 0, ['Stress the new, important information: the number.', 'Yangi va muhim ma’lumotga urg‘u bering: raqamga.', 'Выделяйте новое и важное: число.']),
    item('v3', ['How should a question to the audience sound?', 'Auditoriyaga savol qanday eshitilishi kerak?', 'Как должен звучать вопрос залу?'], [['Like a real question, with the voice rising or a clear pause after.', 'Haqiqiy savoldek, ohang ko‘tarilib yoki keyin aniq pauza bilan.', 'Как настоящий вопрос: с подъёмом голоса или явной паузой после.'], ['Exactly like a statement.', 'Aynan darak gapdek.', 'Точно как утверждение.'], ['As fast as possible.', 'Iloji boricha tez.', 'Как можно быстрее.']], 0, ['A real question invites the room to answer in their heads.', 'Haqiqiy savol tinglovchilarni ichida javob berishga undaydi.', 'Настоящий вопрос приглашает зал ответить про себя.']),
    item('v4', ['What is a simple way to practise vocal variety?', 'Ovoz rang-barangligini mashq qilishning oddiy usuli qaysi?', 'Как просто потренировать выразительность голоса?'], [['Read a short story aloud to a child, as if it mattered.', 'Bolaga qisqa ertakni muhimdek qilib ovoz chiqarib o‘qib bering.', 'Читать вслух короткую сказку ребёнку, как будто это важно.'], ['Whisper the whole talk.', 'Butun nutqni pichirlab ayting.', 'Шептать всю речь.'], ['Speak in one tone to stay calm.', 'Xotirjam bo‘lish uchun bir ohangda gapiring.', 'Говорить одним тоном, чтобы успокоиться.']], 0, ['Stories pull the voice up and down naturally; the habit carries over.', 'Hikoya ovozni tabiiy ravishda ko‘tarib-tushiradi; odat nutqqa o‘tadi.', 'История естественно меняет голос; привычка переходит в речь.']),
    item('v5', ['You want people to remember one line. How do you say it?', 'Odamlar bitta gapni eslab qolishini istaysiz. Uni qanday aytasiz?', 'Вы хотите, чтобы запомнили одну фразу. Как её сказать?'], [['Slower and a little lower, with a pause before it.', 'Sekinroq va biroz pastroq ohangda, oldidan pauza bilan.', 'Медленнее и чуть ниже, с паузой перед ней.'], ['Louder and much faster.', 'Balandroq va ancha tezroq.', 'Громче и намного быстрее.'], ['In the same way as everything else.', 'Boshqa hamma narsadek.', 'Так же, как всё остальное.']], 0, ['Change is what the ear notices: slower and lower signals importance.', 'Quloq o‘zgarishni sezadi: sekin va past ohang muhimlikni bildiradi.', 'Слух замечает перемену: медленнее и ниже — значит важно.']),
    item('v6', ['Your notes for a talk should be…', 'Nutq uchun eslatmalaringizda nima bo‘lishi kerak?', 'Что должно быть в заметках к выступлению?'], [['…a few keywords and your first and last lines.', 'Bir nechta kalit so‘z hamda birinchi va oxirgi gaplaringiz.', 'Несколько ключевых слов, а также ваши первая и последняя фразы.'], ['…the full text, word for word.', 'To‘liq matn, so‘zma-so‘z.', 'Полный текст слово в слово.'], ['…nothing at all, ever.', 'Hech narsa: eslatma umuman kerak emas.', 'Ничего: заметки не нужны никогда.']], 0, ['Keywords keep you on track and let you look at people.', 'Kalit so‘zlar yo‘ldan chiqmaslikka yordam beradi va odamlarga qarashga imkon beradi.', 'Ключевые слова не дают сбиться и позволяют смотреть на людей.']),
    item('v7', ['Why does the coach not score your voice from a typed answer?', 'Nega murabbiy yozilgan javobdan ovozingizni baholamaydi?', 'Почему коуч не оценивает голос по напечатанному ответу?'], [['Because voice and intonation can only be judged from the sound.', 'Chunki ovoz va ohangni faqat tovushdan baholash mumkin.', 'Потому что голос и интонацию можно оценить только по звуку.'], ['Because voice does not matter.', 'Chunki ovoz muhim emas.', 'Потому что голос неважен.'], ['Because it is too hard to explain.', 'Chunki tushuntirish juda qiyin.', 'Потому что это сложно объяснить.']], 0, ['A transcript has your words, not your voice; guessing would be unfair.', 'Matnda so‘zlaringiz bor, ovozingiz emas; taxmin qilish adolatsiz bo‘lardi.', 'В расшифровке есть слова, но не голос; угадывать было бы нечестно.']),
    item('v8', ['A big room and no microphone. What helps most?', 'Katta xona va mikrofon yo‘q. Eng ko‘p nima yordam beradi?', 'Большой зал без микрофона. Что поможет больше всего?'], [['Speak to the back row, slower, with full breaths.', 'Orqa qatorga qarab, sekinroq, to‘liq nafas bilan gapiring.', 'Говорить для последнего ряда, медленнее, на полном дыхании.'], ['Shout every word.', 'Har so‘zni baqirib ayting.', 'Выкрикивать каждое слово.'], ['Speak faster so it is over sooner.', 'Tezroq tugatish uchun tez gapiring.', 'Говорить быстрее, чтобы скорее закончить.']], 0, ['Projection comes from breath and pace, not from shouting.', 'Ovoz kuchi baqiriqdan emas, nafas va sur’atdan keladi.', 'Звучность идёт от дыхания и темпа, а не от крика.']),
  ]),
  drill('drill.plain', 'jargon', 'delivery.clarity', ['Plain words, short sentences', 'Oddiy so‘zlar, qisqa gaplar', 'Простые слова, короткие фразы'], ['Spoken sentences should be short: one idea, under about twenty words. Use the everyday word, explain any term in a phrase, and give numbers a meaning people can picture.', 'Og‘zaki gaplar qisqa bo‘lishi kerak: bitta fikr, taxminan yigirma so‘zdan kam. Oddiy so‘zni ishlating, har atamani bir ibora bilan tushuntiring va raqamlarga ko‘z oldiga keltiriladigan ma’no bering.', 'Устные фразы должны быть короткими: одна мысль, меньше примерно двадцати слов. Выбирайте простые слова, объясняйте термин в двух словах и давайте цифрам понятный смысл.'], [
    item('pl1', ['Which is clearest for parents?', 'Ota-onalar uchun qaysi biri eng aniq?', 'Что понятнее родителям?'], [['The platform optimises engagement metrics via gamification.', 'Platforma geymifikatsiya orqali jalb qilish ko‘rsatkichlarini optimallashtiradi.', 'Платформа оптимизирует метрики вовлечённости через геймификацию.'], ['The app turns homework into short games, so children do it more often.', 'Ilova uy vazifasini qisqa o‘yinlarga aylantiradi, shuning uchun bolalar uni ko‘proq bajaradi.', 'Приложение превращает домашние задания в короткие игры, поэтому дети делают их чаще.'], ['It is a solution for educational processes.', 'Bu ta’lim jarayonlari uchun yechim.', 'Это решение для образовательных процессов.']], 1, ['Say what it does in everyday words, and why it matters.', 'Nima qilishini oddiy so‘zlar bilan va nega muhimligini ayting.', 'Скажите обычными словами, что оно делает и почему это важно.']),
    item('pl2', ['Which phrase means the same as "one in five students" but is harder to picture?', 'Qaysi ibora «har beshta o‘quvchidan biri» bilan bir xil ma’noni bildiradi, lekin uni ko‘z oldiga keltirish qiyinroq?', 'Какая фраза значит то же, что «каждый пятый ученик», но её труднее представить?'], [['"20 percent of the student population".', '«O‘quvchilar populyatsiyasining 20 foizi».', '«20 процентов контингента учащихся».'], ['"one in five students".', '«har beshta o‘quvchidan biri».', '«каждый пятый ученик».'], ['"several students".', '«bir nechta o‘quvchi».', '«несколько учеников».']], 0, ['People can picture "one in five"; a percentage needs translating in their heads.', 'Odamlar «beshtadan biri»ni ko‘z oldiga keltira oladi; foizni esa xayolan tarjima qilish kerak.', '«Каждый пятый» легко представить; процент нужно переводить в уме.']),
    item('pl3', ['You must use the word "algorithm" with a general audience. Best way?', 'Oddiy auditoriya oldida «algoritm» so‘zini ishlatishingiz kerak. Eng yaxshi yo‘l?', 'Нужно сказать «алгоритм» перед широкой аудиторией. Как лучше?'], [['Say it and keep going.', 'Ayting va davom eting.', 'Сказать и продолжить.'], ['Add a short explanation: "a list of steps the computer follows".', 'Qisqa izoh qo‘shing: «kompyuter bajaradigan qadamlar ro‘yxati».', 'Добавить пояснение: «список шагов, которые выполняет компьютер».'], ['Avoid the topic completely.', 'Mavzudan butunlay qoching.', 'Полностью избегать темы.']], 1, ['A one-phrase explanation keeps everyone with you.', 'Bir iboralik izoh hech kimni ortda qoldirmaydi.', 'Пояснение в одну фразу никого не оставляет позади.']),
    item('pl4', ['Which sentence is better for speaking?', 'Gapirish uchun qaysi gap yaxshiroq?', 'Какая фраза лучше для устной речи?'], [['Due to the fact that the budget, which was approved last year after long discussions, is limited, we cannot.', 'O‘tgan yili uzoq muhokamalardan keyin tasdiqlangan byudjet cheklanganligi sababli biz qila olmaymiz.', 'В связи с тем, что бюджет, утверждённый в прошлом году после долгих обсуждений, ограничен, мы не можем.'], ['The budget is small. So we must choose.', 'Byudjet kichik. Shuning uchun tanlashimiz kerak.', 'Бюджет маленький. Поэтому надо выбирать.'], ['Budget-wise, constraints exist.', 'Byudjet nuqtai nazaridan cheklovlar mavjud.', 'С точки зрения бюджета существуют ограничения.']], 1, ['Two short sentences are easier to hear than one long one.', 'Ikkita qisqa gapni bitta uzun gapdan ko‘ra eshitish osonroq.', 'Две короткие фразы воспринимаются легче одной длинной.']),
    item('pl5', ['Which word is too vague?', 'Qaysi so‘z juda noaniq?', 'Какое слово слишком расплывчато?'], [['"stuff", as in "we need some stuff"', '«narsalar», masalan «bizga ba’zi narsalar kerak»', '«всякое», как в «нам нужно всякое»'], ['"twenty chairs"', '«yigirmata stul»', '«двадцать стульев»'], ['"Saturday at nine"', '«shanba kuni soat to‘qqizda»', '«в субботу в девять»']], 0, ['Name the thing: vague words make people stop listening.', 'Narsani nomlang: noaniq so‘zlar tinglashni to‘xtatadi.', 'Называйте вещи: расплывчатые слова выключают внимание.']),
    item('pl6', ['What is the "say it to a twelve-year-old" test?', '«O‘n ikki yoshli bolaga tushuntiring» tekshiruvi nima?', 'Что такое тест «объяснить двенадцатилетнему»?'], [['If a twelve-year-old would understand your key message, it is clear.', 'Agar o‘n ikki yoshli bola asosiy xabaringizni tushunsa, u aniq.', 'Если двенадцатилетний поймёт главную мысль — она ясна.'], ['Only children should hear your talk.', 'Nutqingizni faqat bolalar eshitishi kerak.', 'Речь должны слушать только дети.'], ['Use childish words in every talk.', 'Har nutqda bolalarcha so‘zlar ishlating.', 'Использовать детские слова в каждой речи.']], 0, ['Clear is not childish: it means anyone can follow the main idea.', 'Aniqlik — bolalarchalik emas: bu asosiy fikrni har kim tushuna olishi demak.', 'Ясно — не значит по-детски: это значит, что главную мысль поймёт каждый.']),
    item('pl7', ['Which states the key message plainly?', 'Qaysi biri asosiy xabarni sodda aytadi?', 'Где главная мысль сказана просто?'], [['We should open the library on Saturdays.', 'Kutubxonani shanba kunlari ochishimiz kerak.', 'Нам нужно открывать библиотеку по субботам.'], ['There are various considerations regarding access to resources.', 'Resurslardan foydalanish bo‘yicha turli mulohazalar bor.', 'Существуют различные соображения относительно доступа к ресурсам.'], ['It might be worth thinking about some options.', 'Ba’zi variantlar haqida o‘ylab ko‘rishga arzirmikin.', 'Возможно, стоит подумать о некоторых вариантах.']], 0, ['Say exactly what you want, in one sentence.', 'Nimani xohlayotganingizni aniq, bitta gapda ayting.', 'Скажите точно, чего хотите, одной фразой.']),
    item('pl8', ['An English word slips into your Uzbek or Russian talk. When is it fine?', 'O‘zbekcha yoki ruscha nutqingizga inglizcha so‘z aralashdi. Qachon bu normal?', 'В узбекскую или русскую речь попало английское слово. Когда это нормально?'], [['When your audience uses it every day too.', 'Auditoriyangiz ham uni har kuni ishlatsa.', 'Когда ваша аудитория тоже употребляет его каждый день.'], ['Always: it sounds smarter.', 'Har doim: aqlliroq eshitiladi.', 'Всегда: так звучит умнее.'], ['Never, under any circumstances.', 'Hech qachon, hech qanday holatda.', 'Никогда, ни при каких условиях.']], 0, ['Use the words your listeners use; borrowed words they don’t know are jargon.', 'Tinglovchilaringiz ishlatadigan so‘zlarni ishlating; ular bilmaydigan o‘zlashma so‘zlar esa tushunarsiz jargon.', 'Говорите словами слушателей; незнакомые им заимствования — это жаргон.']),
  ]),
  drill('drill.apology', 'apologising', 'structure.hook', ['Start strong, without apologies', 'Uzrsiz, kuchli boshlang', 'Сильное начало без извинений'], ['Apologising for your nerves, your language or your slides tells people not to listen. The audience sees far less of your nerves than you feel. Replace the apology with your first strong sentence.', 'Hayajoningiz, tilingiz yoki slaydlaringiz uchun uzr so‘rash odamlarga «tinglamasangiz ham bo‘ladi» degandek eshitiladi. Tinglovchilar hayajoningizni siz o‘ylagandan ancha kam sezadi. Uzrni birinchi kuchli gapingiz bilan almashtiring.', 'Извиняясь за волнение, язык или слайды, вы говорите людям «не слушайте». Зал замечает ваше волнение гораздо меньше, чем вам кажется. Замените извинение первой сильной фразой.'], [
    item('a1', ['Which opening is best?', 'Qaysi kirish eng yaxshi?', 'Какое начало лучше?'], [['Sorry, I am very nervous and not a good speaker.', 'Kechirasiz, juda hayajondaman va yaxshi notiq emasman.', 'Извините, я очень волнуюсь и плохо выступаю.'], ['Last year, half our class failed the same test. Here is why.', 'O‘tgan yili sinfimizning yarmi bir xil testdan o‘ta olmadi. Mana sababi.', 'В прошлом году полкласса провалило один и тот же тест. Вот почему.'], ['Sorry, my English is not perfect.', 'Kechirasiz, slaydlarim unchalik yaxshi chiqmadi.', 'Извините, слайды получились так себе.']], 1, ['Start with content; apologies make people expect a weak talk.', 'Mazmun bilan boshlang; uzr odamlarda zaif nutqni kutishga sabab bo‘ladi.', 'Начинайте с содержания; извинения настраивают на слабую речь.']),
    item('a2', ['Your slides do not open. What do you say?', 'Slaydlaringiz ochilmayapti. Nima deysiz?', 'Слайды не открываются. Что вы скажете?'], [['I am so sorry, this is a disaster, give me five minutes.', 'Juda uzr, bu falokat, menga besh daqiqa bering.', 'Мне так жаль, это катастрофа, дайте пять минут.'], ['Let me tell you without the slides; you will see them later.', 'Slaydlarsiz aytib beraman; ularni keyinroq ko‘rasiz.', 'Расскажу без слайдов, их вы увидите позже.'], ['I cannot present without slides.', 'Slaydsiz taqdimot qila olmayman.', 'Без слайдов я не могу выступать.']], 1, ['Calmly carrying on shows you know your material.', 'Xotirjam davom etish materialni bilishingizni ko‘rsatadi.', 'Спокойно продолжая, вы показываете, что знаете материал.']),
    item('a3', ['You made a small mistake in a number. What now?', 'Raqamda kichik xato qildingiz. Endi nima?', 'Вы ошиблись в цифре. Что теперь?'], [['Correct it simply: "Sorry, thirty, not forty," and continue.', 'Oddiygina tuzating: «Kechirasiz, qirq emas, o‘ttiz» va davom eting.', 'Просто поправиться: «Простите, тридцать, а не сорок» — и дальше.'], ['Apologise for a minute about being bad with numbers.', 'Raqamlarga yomonligingiz uchun bir daqiqa uzr so‘rang.', 'Минуту извиняться за то, что не дружите с цифрами.'], ['Pretend nothing happened even though it is wrong.', 'Noto‘g‘ri bo‘lsa ham, hech narsa bo‘lmagandek ko‘rsating.', 'Сделать вид, что ничего не было, хотя цифра неверна.']], 0, ['A quick correction is honest; a long apology steals the moment.', 'Tez tuzatish — halollik; uzoq uzr esa lahzani o‘g‘irlaydi.', 'Быстрая поправка — честно; долгие извинения крадут момент.']),
    item('a4', ['Why avoid "I will try to be quick, I know you are tired"?', 'Nega «Qisqa gapirishga harakat qilaman, charchaganingizni bilaman» deyishdan qochish kerak?', 'Почему не стоит говорить «Постараюсь быстро, знаю, вы устали»?'], [['It tells people your talk is a burden.', 'Bu odamlarga nutqingiz ular uchun yuk ekanini bildiradi.', 'Это говорит людям, что ваша речь — обуза.'], ['It is too polite.', 'Juda odobli.', 'Это слишком вежливо.'], ['It is too short.', 'Juda qisqa.', 'Это слишком коротко.']], 0, ['Respect their time by being clear, not by apologising for being there.', 'Ularning vaqtini shu yerda turganingiz uchun uzr so‘rab emas, aniq gapirib hurmat qiling.', 'Уважайте их время ясностью, а не извинениями за своё присутствие.']),
    item('a5', ['Your hands are shaking at the start. Best move?', 'Boshida qo‘llaringiz titrayapti. Eng yaxshi qadam?', 'В начале у вас дрожат руки. Лучший ход?'], [['Tell the audience your hands are shaking.', 'Tinglovchilarga qo‘llaringiz titrayotganini ayting.', 'Сказать залу, что у вас дрожат руки.'], ['Hold your notes or rest your hands, breathe out slowly, and begin.', 'Eslatmani ushlang yoki qo‘llaringizni stolga qo‘ying, sekin nafas chiqaring va boshlang.', 'Взять заметки или опереть руки, медленно выдохнуть и начать.'], ['Leave and come back later.', 'Chiqib keting va keyinroq qayting.', 'Уйти и вернуться позже.']], 1, ['A slow breath out calms the body; the audience often does not even notice the shaking.', 'Sekin nafas chiqarish tanani tinchlantiradi; tinglovchilar titrashni ko‘pincha sezmaydi ham.', 'Медленный выдох успокаивает тело; дрожь зал часто даже не замечает.']),
    item('a6', ['Which replaces "I am not an expert, but…"?', '«Men mutaxassis emasman, lekin…» o‘rniga qaysi biri?', 'Чем заменить «Я не эксперт, но…»?'], [['"Here is what I found when I tested it myself."', '«Mana, o‘zim sinab ko‘rganimda nimani aniqladim.»', '«Вот что показала моя собственная проверка».'], ['"I don’t really know anything."', '«Men aslida hech narsa bilmayman.»', '«Я, в общем-то, ничего не знаю».'], ['"Maybe someone else should speak."', '«Balki boshqa birov gapirgani ma’qul.»', '«Может, лучше пусть выступит кто-то другой».']], 0, ['Speak from your own experience instead of lowering your authority.', 'Obro‘yingizni tushirish o‘rniga o‘z tajribangizdan gapiring.', 'Говорите из своего опыта, а не принижайте себя.']),
    item('a7', ['When is a short apology right?', 'Qachon qisqa uzr to‘g‘ri bo‘ladi?', 'Когда короткое извинение уместно?'], [['When you really made people wait, once and briefly.', 'Haqiqatan odamlarni kuttirib qo‘yganingizda, bir marta va qisqa.', 'Когда вы действительно заставили людей ждать — один раз и коротко.'], ['At the start of every talk.', 'Har bir nutq boshida.', 'В начале каждого выступления.'], ['After every point.', 'Har bir fikrdan keyin.', 'После каждого тезиса.']], 0, ['Apologise for a real inconvenience, then move on to strength.', 'Haqiqiy noqulaylik uchun uzr so‘rang, keyin kuchli qismga o‘ting.', 'Извинитесь за реальное неудобство и переходите к сильному.']),
    item('a8', ['Which sounds confident without being arrogant?', 'Qaysi biri takabburliksiz ishonchli eshitiladi?', 'Что звучит уверенно, но не высокомерно?'], [['"I am the best speaker here."', '«Men bu yerdagi eng yaxshi notiqman.»', '«Лучше меня здесь никто не выступает».'], ['"I have tested this for three months, and I want to show you what happened."', '«Buni uch oy sinab ko‘rdim va nima bo‘lganini sizga ko‘rsatmoqchiman.»', '«Я уже три месяца это проверяю и хочу показать, что получилось».'], ['"Sorry, this might be boring."', '«Kechirasiz, bu zerikarli bo‘lishi mumkin.»', '«Простите, это может быть скучно».']], 1, ['Confidence comes from facts about your work, not claims about yourself.', 'Ishonch o‘zingiz haqidagi da’volardan emas, ishingiz haqidagi faktlardan keladi.', 'Уверенность — в фактах о работе, а не в заявлениях о себе.']),
  ]),
  drill('drill.qa', 'weak_answer', 'interaction.qa', ['Answer hard questions well', 'Qiyin savollarga yaxshi javob', 'Ответы на трудные вопросы'], ['Answer first in one sentence, then one reason or example, then stop. With a hostile question: stay calm, thank them, acknowledge what is fair, answer the core. If you do not know, say so and promise to follow up — never invent.', 'Avval bitta gap bilan javob bering, keyin bitta sabab yoki misol, keyin to‘xtang. Hujumkor savolda: xotirjam bo‘ling, rahmat ayting, adolatli tomonini tan oling, asosiga javob bering. Bilmasangiz, shuni ayting va keyinroq javob berishni va’da qiling — hech qachon to‘qimang.', 'Сначала ответ одной фразой, затем одна причина или пример — и стоп. На враждебный вопрос: спокойствие, благодарность, признание справедливого, ответ по сути. Не знаете — скажите и пообещайте вернуться с ответом, но никогда не выдумывайте.'], [
    item('qa1', ['"How much will it cost?" Which answer is best?', '«Bu qanchaga tushadi?» Qaysi javob eng yaxshi?', '«Сколько это будет стоить?» Какой ответ лучше?'], [['Well, it depends on many things, like the season, the supplier, and so on…', 'Bu ko‘p narsaga bog‘liq, masalan mavsum, yetkazib beruvchi va hokazo…', 'Ну, это зависит от многого: сезон, поставщик и так далее…'], ['About two million sum for the first term. Most of it is the kits.', 'Birinchi chorak uchun taxminan ikki million so‘m. Ko‘p qismi to‘plamlar uchun.', 'Около двух миллионов сумов на первую четверть. Большая часть — наборы.'], ['Money is not the important thing here.', 'Bu yerda pul muhim emas.', 'Деньги здесь не главное.']], 1, ['The number first, then one line of reason.', 'Avval raqam, keyin bir gaplik sabab.', 'Сначала цифра, затем одна фраза-пояснение.']),
    item('qa2', ['You don’t know the answer. What do you say?', 'Javobni bilmaysiz. Nima deysiz?', 'Вы не знаете ответа. Что скажете?'], [['Make up a likely number.', 'Ishonarli raqam o‘ylab toping.', 'Придумать правдоподобную цифру.'], ['"I don’t know yet. I will check and send it to you today."', '«Hozircha bilmayman. Tekshirib, bugun sizga yuboraman.»', '«Пока не знаю. Проверю и пришлю вам сегодня».'], ['"That is not important."', '«Bu muhim emas.»', '«Это неважно».']], 1, ['Honesty plus a follow-up builds more trust than a guess.', 'Halollik va keyinroq javob berish va’dasi taxmindan ko‘ra ko‘proq ishonch uyg‘otadi.', 'Честность и обещание ответа вызывают больше доверия, чем догадка.']),
    item('qa3', ['"This idea will never work." Best start to your answer?', '«Bu g‘oya hech qachon ishlamaydi.» Javobni qanday boshlash eng yaxshi?', '«Эта идея никогда не сработает». Как лучше начать ответ?'], [['"You are wrong."', '«Siz adashyapsiz.»', '«Вы не правы».'], ['"I understand the doubt. Here is what we tested."', '«Shubhangizni tushunaman. Mana, biz nimalarni sinab ko‘rdik.»', '«Понимаю ваши сомнения. Вот что мы проверили».'], ['"OK, maybe you are right, let’s forget it."', '«Xo‘p, balki haqsiz, unutaylik.»', '«Ладно, может, вы правы, забудем».']], 1, ['Acknowledge, then evidence: no fight and no surrender.', 'Tan oling, keyin dalil: na janjal, na taslim bo‘lish.', 'Признание, затем факты: без спора и без капитуляции.']),
    item('qa4', ['How long should a Q&A answer usually be?', 'Savol-javobdagi javob odatda qancha bo‘lishi kerak?', 'Какой обычно должна быть длина ответа на вопрос?'], [['About three to five sentences.', 'Taxminan uch-besh gap.', 'Примерно три-пять предложений.'], ['As long as your talk.', 'Nutqingiz kabi uzun.', 'Как всё ваше выступление.'], ['One word.', 'Bitta so‘z.', 'Одно слово.']], 0, ['Short answers leave time for more people and keep the room.', 'Qisqa javoblar ko‘proq odam uchun vaqt qoldiradi va zal diqqatini ushlab turadi.', 'Короткие ответы оставляют время другим и держат зал.']),
    item('qa5', ['The question is very long and unclear. What now?', 'Savol juda uzun va noaniq. Endi nima?', 'Вопрос очень длинный и неясный. Что делать?'], [['Answer whatever you think they meant.', 'Ular nima nazarda tutgan deb o‘ylasangiz, shunga javob bering.', 'Ответить так, как вы поняли.'], ['Repeat the question in one short sentence and check it.', 'Savolni bitta qisqa gap bilan takrorlang va to‘g‘ri tushunganingizni so‘rang.', 'Пересказать вопрос одной фразой и уточнить.'], ['Say it is not a real question.', 'Bu haqiqiy savol emasligini ayting.', 'Сказать, что это не вопрос.']], 1, ['"So you are asking whether…?" makes sure you answer the right thing.', '«Demak, siz … deb so‘rayapsizmi?» to‘g‘ri narsaga javob berishingizni ta’minlaydi.', '«То есть вы спрашиваете, …?» — и вы ответите на нужное.']),
    item('qa6', ['Someone asks the same question again. What does it mean?', 'Kimdir xuddi shu savolni yana berdi. Bu nimani anglatadi?', 'Вас спрашивают о том же второй раз. Что это значит?'], [['Your first answer did not really answer it.', 'Birinchi javobingiz unga haqiqatan javob bermagan.', 'Первый ответ на самом деле не отвечал на вопрос.'], ['They were not listening.', 'Ular tinglamagan.', 'Человек не слушал.'], ['They want to annoy you.', 'Ular sizni asabiylashtirmoqchi.', 'Вас хотят разозлить.']], 0, ['This time, give a direct answer in your first sentence.', 'Bu safar birinchi gapdayoq to‘g‘ridan-to‘g‘ri javob bering.', 'На этот раз дайте прямой ответ первой же фразой.']),
    item('qa7', ['How do you bridge back to your message after an answer?', 'Javobdan keyin xabaringizga qanday qaytasiz?', 'Как вернуться к своей мысли после ответа?'], [['"…and that is exactly why the trial matters."', '«…aynan shuning uchun sinov muhim.»', '«…и именно поэтому пробный запуск важен».'], ['Start the whole talk again.', 'Butun nutqni qaytadan boshlang.', 'Начать всё выступление заново.'], ['Change the subject to something else.', 'Mavzuni boshqa narsaga o‘zgartiring.', 'Сменить тему.']], 0, ['One linking line connects the answer to your main point.', 'Bitta bog‘lovchi gap javobni asosiy fikringizga ulaydi.', 'Одна связующая фраза соединяет ответ с главной мыслью.']),
    item('qa8', ['Which reply to a rude question is best?', 'Qo‘pol savolga qaysi javob eng yaxshi?', 'Какой ответ на грубый вопрос лучше?'], [['Answer the useful part calmly and ignore the tone.', 'Foydali qismiga xotirjam javob bering, ohangga e’tibor bermang.', 'Спокойно ответить на полезную часть и не реагировать на тон.'], ['Be rude back so people see you are strong.', 'Kuchli ekaningizni ko‘rsatish uchun qo‘pol javob qaytaring.', 'Ответить грубостью, чтобы показать силу.'], ['Refuse to answer.', 'Javob berishdan bosh torting.', 'Отказаться отвечать.']], 0, ['The room watches how you react; calm wins them.', 'Zal munosabatingizni kuzatib turadi; xotirjamligingiz uning hurmatini qozonadi.', 'Зал смотрит на вашу реакцию; спокойствие его завоёвывает.']),
  ]),
  drill('drill.examples', 'no_example', 'content.examples', ['Back every point with an example', 'Har fikrni misol bilan quvvatlang', 'Пример к каждому тезису'], ['People remember stories and examples far better than general claims. After each point, add one concrete thing: a person, a place, a moment, or a number you know is true.', 'Odamlar umumiy gaplardan ko‘ra hikoya va misollarni ancha yaxshi eslab qoladi. Har bir fikrdan keyin bitta aniq narsa qo‘shing: odam, joy, lahza yoki to‘g‘riligini aniq bilgan raqamingiz.', 'Истории и примеры запоминаются гораздо лучше общих слов. После каждого тезиса добавляйте что-то конкретное: человека, место, момент или цифру, в которой вы уверены.'], [
    item('e1', ['"Reading is useful." Which example makes it stick?', '«Kitob o‘qish foydali.» Qaysi misol uni esda qoldiradi?', '«Чтение полезно». Какой пример делает это запоминающимся?'], [['Many studies show reading is good.', 'Ko‘p tadqiqotlar o‘qish yaxshi ekanini ko‘rsatadi.', 'Многие исследования говорят, что чтение полезно.'], ['My brother read twenty pages a day for a year and went from a C to an A in literature.', 'Akam bir yil kuniga yigirma sahifa o‘qidi va adabiyotdan «3»dan «5»ga chiqdi.', 'Мой брат год читал по двадцать страниц в день и поднялся по литературе с тройки до пятёрки.'], ['Reading is very, very useful.', 'O‘qish juda-juda foydali.', 'Чтение очень-очень полезно.']], 1, ['A real person and a change people can picture.', 'Haqiqiy inson va ko‘z oldiga keltiriladigan o‘zgarish.', 'Реальный человек и изменение, которое легко представить.']),
    item('e2', ['Which is a concrete detail?', 'Qaysi biri aniq tafsilot?', 'Что является конкретной деталью?'], [['"The queue at the bank went out the door at nine a.m."', '«Ertalab soat to‘qqizda bankdagi navbat ko‘chagacha cho‘zilgan edi.»', '«В девять утра очередь в банке тянулась до самой улицы».'], ['"There are often problems with services."', '«Xizmatlarda ko‘pincha muammolar bo‘ladi.»', '«С услугами часто бывают проблемы».'], ['"Things could be better."', '«Ishlar yaxshiroq bo‘lishi mumkin.»', '«Всё могло бы быть лучше».']], 0, ['A detail you can see makes the problem real.', 'Ko‘rish mumkin bo‘lgan tafsilot muammoni haqiqiy qiladi.', 'Деталь, которую можно увидеть, делает проблему реальной.']),
    item('e3', ['You have no statistic. What is the best example?', 'Sizda statistika yo‘q. Eng yaxshi misol qaysi?', 'У вас нет статистики. Какой пример лучше?'], [['Invent a believable number.', 'Ishonarli raqam o‘ylab toping.', 'Придумать правдоподобную цифру.'], ['Tell one short real moment you saw yourself.', 'O‘zingiz ko‘rgan bitta qisqa haqiqiy lahzani aytib bering.', 'Рассказать о коротком реальном случае, который вы видели сами.'], ['Skip examples.', 'Misolsiz qoldiring.', 'Обойтись без примеров.']], 1, ['A true small story beats an invented number every time.', 'Haqiqiy kichik hikoya har doim to‘qima raqamdan ustun.', 'Правдивая маленькая история всегда лучше выдуманной цифры.']),
    item('e4', ['Where should an example go?', 'Misol qayerda bo‘lishi kerak?', 'Где должен стоять пример?'], [['Right after the point it supports.', 'U quvvatlaydigan fikrdan darhol keyin.', 'Сразу после тезиса, который он подтверждает.'], ['All examples together at the very end.', 'Barcha misollar oxirida birga.', 'Все примеры вместе в самом конце.'], ['Before the hook.', 'Kirishdan oldin.', 'До зацепки.']], 0, ['Point, then example: the listener links them at once.', 'Fikr, keyin misol: tinglovchi ularni darhol bog‘laydi.', 'Тезис, затем пример — слушатель сразу их связывает.']),
    item('e5', ['Which is the best example for a pitch about a tutoring club?', 'Repetitorlik to‘garagi taqdimoti uchun qaysi misol eng yaxshi?', 'Какой пример лучше всего для питча о клубе репетиторства?'], [['"Tutoring is a well-known method."', '«Repetitorlik — mashhur usul.»', '«Репетиторство — известный метод».'], ['"Last week Ali explained fractions to Bobur in ten minutes, and Bobur finally got it."', '«O‘tgan hafta Ali Boburga kasrlarni o‘n daqiqada tushuntirdi va Bobur nihoyat tushundi.»', '«На прошлой неделе Али за десять минут объяснил Бобуру дроби, и тот наконец понял».'], ['"Education is the key to the future."', '«Ta’lim — kelajak kaliti.»', '«Образование — ключ к будущему».']], 1, ['A tiny real scene shows the idea working.', 'Kichkina haqiqiy sahna g‘oya ishlayotganini ko‘rsatadi.', 'Маленькая реальная сцена показывает, что идея работает.']),
    item('e6', ['How many examples per main point?', 'Har asosiy fikrga nechta misol?', 'Сколько примеров на один тезис?'], [['One strong one is usually enough.', 'Odatda bitta kuchli misol yetarli.', 'Обычно достаточно одного сильного.'], ['At least five.', 'Kamida beshta.', 'Не меньше пяти.'], ['None; examples waste time.', 'Umuman kerak emas; misollar vaqtni bekorga oladi.', 'Ни одного; примеры тратят время.']], 0, ['One vivid example is remembered; five blur together.', 'Bitta yorqin misol eslab qolinadi; beshtasi aralashib ketadi.', 'Один яркий пример запоминается, пять — сливаются.']),
    item('e7', ['Which turns a claim into evidence?', 'Qaysi biri da’voni dalilga aylantiradi?', 'Что превращает утверждение в довод?'], [['Saying it more loudly.', 'Uni balandroq aytish.', 'Сказать громче.'], ['Adding where you saw it or how you measured it.', 'Qayerda ko‘rganingiz yoki qanday o‘lchaganingizni qo‘shish.', 'Добавить, где вы это видели или как измерили.'], ['Repeating it three times.', 'Uni uch marta takrorlash.', 'Повторить три раза.']], 1, ['"We counted for one week" makes a number believable.', '«Bir hafta davomida sanadik» degan gap raqamni ishonarli qiladi.', '«Мы считали неделю» делает цифру убедительной.']),
    item('e8', ['A story example should include…', 'Hikoya shaklidagi misolda nima bo‘lishi kerak?', 'Пример-история должен содержать…'], [['…who, where, what happened and what changed.', 'Kim, qayerda, nima bo‘ldi va nima o‘zgardi.', '…кто, где, что случилось и что изменилось.'], ['…every detail you remember.', 'Eslagan har bir tafsilotingiz.', '…каждую деталь, которую вы помните.'], ['…only the moral at the end.', 'Faqat oxiridagi xulosa.', '…только мораль в конце.']], 0, ['Four parts in a few sentences make a story that works.', 'Bir necha gapdagi to‘rt qism ishlaydigan hikoyani yaratadi.', 'Четыре части в нескольких фразах — и история работает.']),
  ]),
];
